package co.sena.academic.adapter.in.rest.mapper; import co.sena.academic.adapter.in.rest.dto.*; import co.sena.academic.application.port.in.QueryLearningOutcomesUseCase; import co.sena.academic.domain.model.LearningOutcome; import org.springframework.stereotype.Component; @Component public class LearningOutcomeRestMapper {public LearningOutcomeResponse toResponse(LearningOutcome v){return new LearningOutcomeResponse(v.getId(),v.getCompetencyId(),v.getCode(),v.getDescription(),v.isActive(),v.getRowVersion(),v.getCreatedAt(),v.getUpdatedAt());}public LearningOutcomePageResponse toPageResponse(QueryLearningOutcomesUseCase.Page p){int pages=p.size()==0?0:(int)Math.ceil((double)p.totalElements()/p.size());return new LearningOutcomePageResponse(p.content().stream().map(this::toResponse).toList(),new LearningOutcomePageResponse.Pagination(p.page()+1,p.size(),p.totalElements(),pages));}}
